mutation login($emailAddress: EmailAddress!, $password: String!) {
  login(emailAddress: $emailAddress, password: $password) {
    __typename
    errorMessage
    message
    accountToken
    tokenExpiry
    me {
      __typename
      emailAddress
      phoneNumber
      firstName
      lastName
      userId
      company
      position
    }
  }
}

